#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        if(pos==n-1){
            // Element at last position, bring to 'placed'
            // op(x=placed, y=1): but need placed>0
            // new[0]=p[n-1]=our element, then middle, then prefix
            // our element goes to position 0, but we want 'placed'
            // op(x, y=n-1-pos)... element at n-1, y=1 puts it at position 0
            // We want it at position 'placed'. Use x=placed, y=n-placed-1? 
            // Then element at pos=n-1 >= n-y = n-(n-placed-1)=placed+1, so new pos = pos-(placed+1) = n-2-placed
            // That's not placed. Let's try: x=placed+1, y=1 (if placed+1+1<n i.e. placed<n-2)
            // element at n-1 >= n-1, new pos = n-1-(n-1)=0... no, we want placed not 0
            if(placed==0){
                apply_op(1,1); // element at n-1 goes to pos 0
            } else {
                // Use x=placed, y=n-placed-1 wouldn't help. 
                // Two-step: first op to bring to some position, then fix
                // Actually: op(placed, 1): element at n-1, y=1, new pos=n-1-(n-1)=0. Then everything shifts. Not placed.
                // op with y = n-pos = 1: suffix=[n-1]. New pos of element = 0. Prefix [0..x-1] goes to end.
                // If x=placed, new array: [element] + [placed..n-2] + [0..placed-1]. Element at 0, not placed.
                // Need: make suffix include positions [placed..n-1] somehow? x=placed, y=n-placed-1... x+y=n-1<n. Element at n-1: n-1>=n-(n-placed-1)=placed+1, so new pos=n-1-(placed+1)=n-placed-2. Not helpful.
                // Just do 2 ops: bring to front then to placed
                apply_op(1, 1); // element goes to pos 0
                pos=0;
                if(placed>0 && placed+1<n){
                    apply_op(1, n-placed-1);
                    // pos 0 < x=1: new pos = n-1+0 = n-1. Nope...
                    // Ugh. Let me recalc: pos=0 < x=1, new pos = n - x + pos = n-1. Wrong direction.
                    // Instead: after element at 0, use op(placed+1, n-placed-1): x+y=n, invalid.
                    // op(placed, n-placed-1): element at 0<placed(if placed>0), new pos=n-placed+0=n-placed. Not placed.
                    // Hmm, let me just re-find and continue
                    for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
            }
        }
        // General case: element at pos, want at placed, placed<pos<n
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: bring element to position 0
        // pos < n, x=1, y=n-pos: new pos of element = pos-(n-(n-pos))=pos-pos=0. x+y=1+n-pos, need <n => pos>1
        // If pos==1: x=1,y=n-1, x+y=n not <n. Use x=2,y=n-2: element at 1<x=2, new pos=n-2+1=n-1.
        if(pos>1){
            apply_op(1, n-pos);
            pos=0;
        } else if(pos==1){
            apply_op(2, n-2);
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos!=placed && pos>1){
                apply_op(1, n-pos);
                pos=0;
            }
        }
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Step 2: element at pos=0, bring to 'placed'
        if(pos==0 && placed>0 && placed<n-1){
            // x=1, y=n-1-placed: element at 0<1, new pos = n-1+0=n-1. Bad.
            // x= ?, y=?: want new_pos=placed for old_pos=0.
            // old_pos<x => new_pos = n-x+0 = n-x. Want n-x=placed => x=n-placed. y>0,x+y<n => y<placed. y>=1 => placed>1.
            if(placed>1){
                apply_op(n-placed, 1);
            } else { // placed==1
                apply_op(n-1, 1); // x+y=n, invalid if n>2. x=n-1,y=1,x+y=n. Bad.
                // placed=1: x=n-placed=n-1, y must be >=1, x+y>=n. Need smaller x.
                // new_pos=1 for old_pos=0: n-x=1 => x=n-1. Same issue.
                // Use 2 ops: move to end first
                apply_op(1, n-2); // pos0 -> n-1+0=n-1... no, n-1. 
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if(pos!=placed) apply_op(1, n-pos>0&&1+n-pos<n ? n-pos : 1);
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
